class Solution {
  public boolean canMakeEqual(int[] nums, int k) {
    for (int target = -1; target <= 1; target += 2) {
      int[] a = nums.clone();
      int ops = 0;
      for (int i = 0; i + 1 < a.length; i++) {
        if (a[i] != target) {
          a[i] = -a[i];
          a[i + 1] = -a[i + 1];
          ops++;
        }
      }
      if (a[a.length - 1] == target && ops <= k) return true;
    }
    return false;
  }
}
